import type { ThermalGroup } from "@labirthermal/core";
import { ThermalFileInstance, ThermalFileFailure } from "@labirthermal/core";
import { ContextConsumer } from "@lit/context";
import type { PropertyValueMap } from "lit";
import type { IBaseElement } from "../AbstractThermalElement";
import type { HostReactiveProperties } from "./AbstractHierarchyController";
import { AbstractHierarchyController } from "./AbstractHierarchyController";
import type { FileController } from "./FileController";
import type { GroupController } from "./GroupController";
import { groupControllerContext } from "./GroupController";

type IHostProperties = {

    thermal: string | undefined,
    visible: string | undefined

}

/** 
 * An element that implements `FileLoadController` 
 * @see {@link FileLoadController}
 */
export interface IElementWithFileLoadController extends IBaseElement, IHostProperties {
    fileController: FileController,
    fileLoadController: FileLoadController,
    groupController: GroupController
}

/** 
 * When appended to an element with `FileController`, takes care of loading the file from the host attributes such as `thermal` and `visible`.
 * 
 * The element using `FileLoadController` needs to implement `IElementWithFileLoadController`
 * 
 * Public reactive properties of the host:
 * - `thermal`: The thermal file to be loaded.
 * - `visible`: The visibility setting for the thermal file.
 * 
 * @see {@link FileLoadController.HOST_PROPERTIES}
 * 
 * @module @labirthermal/webcomponents
 * @author Jan Jáchim <jachim@gmail.com>
 * */
export class FileLoadController extends AbstractHierarchyController<IElementWithFileLoadController> {

    private _UUID: string;

    public get UUID(): string {
        return this._UUID;
    }

    private _groupController?: GroupController;
    private _requestedGroup?: ThermalGroup;
    private _requestedThermal?: string;
    private _requestedVisible?: string;
    private readonly groupControllerConsumer: ContextConsumer<typeof groupControllerContext, IElementWithFileLoadController>;
    private readonly handleGroupCreated = (): void => this._loadCurrentThermal();


    public static readonly HOST_PROPERTIES: HostReactiveProperties<IHostProperties> = {
        thermal: { type: String, reflect: true, attribute: "thermal" },
        visible: { type: String, reflect: true, attribute: "visible" }
    }

    constructor(
        host: IElementWithFileLoadController
    ) {
        super(host);
        this._UUID = host.UUID;

        this.groupControllerConsumer = new ContextConsumer(this.host, {
            context: groupControllerContext,
            callback: groupController => {
                this.host.groupController = groupController;
                this._subscribeToGroup(groupController);
            }
        });
    }

    hostWillUpdateWatcher(value: PropertyValueMap<IElementWithFileLoadController>): void {
        if (value.has("thermal") || value.has("visible")) {
            this._requestedGroup = undefined;
            this._requestedThermal = undefined;
            this._requestedVisible = undefined;
            this._loadCurrentThermal();
        }
    }


    hostUpdatedWatcher(): void {
        // Do nothing for now
    }
    

    hostConnected(): void {
        if (this.host.groupController) {
            this._subscribeToGroup(this.host.groupController);
        }
        this._loadCurrentThermal();
    }


    hostDisconnected(): void {
        this._groupController?.onInternalObject.delete(this.UUID);
        this._groupController = undefined;
    }

    private _subscribeToGroup(groupController: GroupController): void {
        if (this._groupController !== groupController) {
            this._groupController?.onInternalObject.delete(this.UUID);
            this._groupController = groupController;
        }

        groupController.onInternalObject.set(this.UUID, this.handleGroupCreated);
        this._loadCurrentThermal();
    }

    private _loadCurrentThermal(): void {
        const thermal = this.host.thermal;
        const group = this._groupController?.groupObject;

        if (!thermal) {
            this._requestedGroup = undefined;
            this._requestedThermal = undefined;
            this._requestedVisible = undefined;

            const file = this.host.fileController.fileObject;
            if (file && group) {
                group.files.removeFile(file);
                this.host.fileController.removeInstance();
            }
            return;
        }

        if (!group || (
            this._requestedGroup === group
            && this._requestedThermal === thermal
            && this._requestedVisible === this.host.visible
        )) {
            return;
        }

        this._requestedGroup = group;
        this._requestedThermal = thermal;
        this._requestedVisible = this.host.visible;
        void this._load(thermal, this.host.visible, group);
    }

    private async _load(
        lrc: string,
        visible: string | undefined,
        group: ThermalGroup
    ) {

        // If there is a file already, remove it from the group
        if (this.host.fileController.fileObject) {
            group.files.removeFile(this.host.fileController.fileObject);
        }

        this.host.fileController.startLoading();

        const result = group.registry.batch.request(
            lrc,
            visible,
            group,
            async (result) => {
                if (result instanceof ThermalFileInstance) {
                    this.host.fileController.receiveInstance(result);
                } else if (result instanceof ThermalFileFailure) {
                    this.host.fileController.receiveFailure(result);
                }
            }
        );

        return result;

    }




}