import type { ThermalGroup } from "@labirthermal/core";
import { CallbacksManager } from "@labirthermal/core";
import { ContextConsumer, ContextProvider, createContext } from "@lit/context";
import { booleanConverter } from "../../utils/converters/booleanConverter";
import type { IBaseElement } from "../AbstractThermalElement";
import type { HostReactiveProperties } from "./AbstractHierarchyController";
import { AbstractHierarchyController, INTERNAL_STATE_DECLARATION } from "./AbstractHierarchyController";
import type { ManagerController } from "./ManagerController";
import type { RegistryController } from "./RegistryController";
import { registryControllerContext } from "./RegistryController";

type IHostProperties = {

    managerController: ManagerController;

    registryController: RegistryController;

    groupSlug: string;

    groupObject: ThermalGroup;

    groupController: GroupController;

    autoclearGroup: boolean;

}
/**
 * Host properties required by the `GroupController`.
 * 
 * @see {@link GroupController}
 * @see {@link GroupController.HOST_PROPERTIES}
 */
export interface IElementWithGroupController extends IHostProperties, IBaseElement {}

/**
 * Exposes the `GroupController` instance to the `AbstractGroupConsumer` elements.
 * @see {@link GroupController}
 * @module @labirthermal/embed
 * @author Jan Jáchim <jachim@zcu.cz>
 */
export const groupControllerContext = createContext<GroupController>("group-controller-context");

/**
 * Exposes the internal `ThermalGroup` object from the `GroupController`.
 * 
 * @see {@link GroupController}
 * @see {@link ThermalGroup}
 * @module @labirthermal/embed
 * @author Jan Jáchim <jachim@zcu.cz>
 */
export const groupObjectContext = createContext<ThermalGroup>("group-object-context");

export class GroupController extends AbstractHierarchyController<IElementWithGroupController> {
    

    private _UUID: string;

    public get UUID(): string {
        return this._UUID;
    }

    public static readonly HOST_PROPERTIES: HostReactiveProperties<IHostProperties> = {
        managerController: INTERNAL_STATE_DECLARATION,
        registryController: INTERNAL_STATE_DECLARATION,
        groupSlug: { type: String, reflect: true, attribute: "group-slug" },
        groupObject: INTERNAL_STATE_DECLARATION,
        autoclearGroup: { type: Boolean, reflect: true, attribute: "autoclear-group", converter: booleanConverter(true) },
        groupController: INTERNAL_STATE_DECLARATION
    }

    public get groupObject(): ThermalGroup {
        return this.host.groupObject;
    }

    public get registryController(): RegistryController { return this.host.registryController; }

    // Accessors to the host attributes
    public get slug(): string { return this.host.groupSlug; }
    public get autoclearGroup(): boolean { return this.host.autoclearGroup; }

    // Context providers

    private groupControllerContextProvider: ContextProvider<typeof groupControllerContext, IElementWithGroupController>;

    private groupObjectContextProvider: ContextProvider<typeof groupObjectContext, IElementWithGroupController>;

    public readonly onInternalObject = new CallbacksManager< (manager: ThermalGroup) => void >();

    private readonly registryControllerConsumer: ContextConsumer<typeof registryControllerContext, IElementWithGroupController>;

    private _registryController?: RegistryController;

    private _activeRegistryController?: RegistryController;

    private readonly handleRegistryCreated = (): void => {
        if (this._registryController) {
            this._initialize(this._registryController);
        }
    };


    constructor(
        host: IElementWithGroupController
    ) {
        super(host);
        
        this._UUID = host.UUID + "_group-controller";

        this.groupControllerContextProvider = new ContextProvider(
            this.host, 
            { context:  groupControllerContext, initialValue: this }
        );

        this.groupObjectContextProvider = new ContextProvider(
            this.host,
            { context: groupObjectContext }
        );

        this.registryControllerConsumer = new ContextConsumer(this.host, {
            context: registryControllerContext,
            callback: registryController => {
                this._subscribeToRegistry(registryController);
            }
        });

    }

    hostConnected() {

        if (this.host.registryController) {
            this._subscribeToRegistry(this.host.registryController);
        }

    }

    hostDisconnected() {

        if (this.autoclearGroup && this.host.groupObject && this._activeRegistryController) {
            this._activeRegistryController.removeGroup(this.host.groupObject);
        }
        this._registryController?.onInternalObject.delete(this.UUID);
        this._registryController = undefined;
        this._activeRegistryController = undefined;

    }

    hostWillUpdateWatcher(): void {
        // Do nothing
    }

    hostUpdatedWatcher(): void {
        // Do nothing
    }

    private _initialize(registryController: RegistryController): void {
        if (!this.host.isConnected || !registryController.registryObject) {
            return;
        }

        const slug = this._getDefaultSlugFromHost("group-slug");
        const group = registryController.addOrGetGroup(slug);

        if (
            this._activeRegistryController
            && this._activeRegistryController !== registryController
            && this.autoclearGroup
            && this.host.groupObject
        ) {
            this._activeRegistryController.removeGroup(this.host.groupObject);
        }

        this.host.registryController = registryController;
        this.host.groupSlug = slug;
        this.host.groupObject = group;
        this.groupObjectContextProvider.setValue(group);

        if (this._activeRegistryController === registryController) {
            return;
        }

        this._activeRegistryController = registryController;
        this.onInternalObject.call(group);
    }

    private _subscribeToRegistry(registryController: RegistryController): void {
        if (this._registryController !== registryController) {
            this._registryController?.onInternalObject.delete(this.UUID);
            this._registryController = registryController;
        }

        this.host.registryController = registryController;
        registryController.onInternalObject.set(this.UUID, this.handleRegistryCreated);

        if (registryController.registryObject) {
            this._initialize(registryController);
        }
    }




}
